"""Tests for scripts/run_meta.py — run scoping and subagent token accounting.

Both behaviours here were regressions found in the field. A run measured at 1.7h
reported 173.8h and a 15x token count because nothing bounded the transcript
read; and every run after the CLI changed its subagent-usage rendering reported
zero subagent tokens because the regex still matched only the older form.
"""

import json
from pathlib import Path

import pytest

from scripts import run_meta


def _record(ts: str, *, text: str = "", usage: dict | None = None, rtype: str) -> str:
    msg: dict = {"role": "assistant" if rtype == "assistant" else "user"}
    if usage is not None:
        msg["usage"] = usage
        msg["model"] = "claude-opus-5"
    if text:
        msg["content"] = text
    return json.dumps({"timestamp": ts, "type": rtype, "message": msg})


@pytest.fixture
def proj(tmp_path: Path) -> Path:
    (tmp_path / "p").mkdir()
    return tmp_path / "p"


# ---------------------------------------------------------------------------
# subagent token formats


def test_counts_both_subagent_renderings(proj: Path):
    """The tag form and the colon form both count, and both land in the total."""
    (proj / "s.jsonl").write_text(
        "\n".join(
            [
                _record(
                    "2026-01-01T00:00:00Z",
                    text="<subagent_tokens>1000</subagent_tokens>",
                    rtype="user",
                ),
                _record(
                    "2026-01-01T00:01:00Z",
                    text="subagent_tokens: 2500\\ntool_uses: 4",
                    rtype="user",
                ),
            ]
        )
    )
    stats = run_meta.read_tokens(proj)
    assert stats.subagent_count == 2
    assert stats.subagent_tokens == 3500


def test_colon_form_counts_without_a_trailing_tool_uses(proj: Path):
    """Anchoring on `tool_uses` was measured to drop real results."""
    (proj / "s.jsonl").write_text(
        _record("2026-01-01T00:00:00Z", text="subagent_tokens: 77", rtype="user")
    )
    assert run_meta.read_tokens(proj).subagent_tokens == 77


def test_assistant_prose_quoting_the_marker_is_not_counted(proj: Path):
    """SKILL.md requires pasting the report — which prints the literal — into
    the reply, so assistant records routinely contain it as prose."""
    (proj / "s.jsonl").write_text(
        "\n".join(
            [
                _record(
                    "2026-01-01T00:00:00Z",
                    text="subagent_tokens: 500",
                    rtype="user",
                ),
                _record(
                    "2026-01-01T00:02:00Z",
                    text="the report said subagent_tokens: 7,596,926 across 92",
                    rtype="assistant",
                ),
            ]
        )
    )
    stats = run_meta.read_tokens(proj)
    assert stats.subagent_count == 1
    assert stats.subagent_tokens == 500


